<?php session_start(); require __DIR__.'/../includes/db.php'; if(!isset($_SESSION['user_id'])){header('Location: ../login.php');exit;} if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: ../shop.php');exit;} $uid=(int)$_SESSION['user_id'];$pid=(int)($_POST['product_id']??0);$qty=max(1,(int)($_POST['quantity']??1));$st=mysqli_prepare($conn,"SELECT stock FROM products WHERE id=?");mysqli_stmt_bind_param($st,'i',$pid);mysqli_stmt_execute($st);$p=mysqli_fetch_assoc(mysqli_stmt_get_result($st));if(!$p){header('Location: ../shop.php');exit;}if($qty>$p['stock'])$qty=(int)$p['stock'];$st=mysqli_prepare($conn,"INSERT INTO cart(user_id,product_id,quantity) VALUES(?,?,?) ON DUPLICATE KEY UPDATE quantity=LEAST(quantity+VALUES(quantity),?)");mysqli_stmt_bind_param($st,'iiii',$uid,$pid,$qty,$p['stock']);mysqli_stmt_execute($st);header('Location: ../cart.php');exit; ?>